def componentes_conectados(grafo: dict) -> list[set]:
    """Encuentra los componentes conectados de un grafo no dirigido."""
    visitados = set()
    componentes = []

    def dfs(nodo, componente):
        visitados.add(nodo)
        componente.add(nodo)
        for vecino in grafo.get(nodo, []):
            if vecino not in visitados:
                dfs(vecino, componente)

    for nodo in grafo:
        if nodo not in visitados:
            c = set()
            dfs(nodo, c)
            componentes.append(c)
    return componentes

grafo = {"A": ["B"], "B": ["A"], "C": ["D"], "D": ["C"], "E": []}
print(componentes_conectados(grafo))

def dfs(grafo: dict, inicio: str, visitados: set = None) -> list:
    """DFS — Búsqueda en Profundidad recursiva."""
    if visitados is None:
        visitados = set()
    visitados.add(inicio)
    orden = [inicio]
    for vecino in grafo.get(inicio, []):
        if vecino not in visitados:
            orden.extend(dfs(grafo, vecino, visitados))
    return orden

grafo = {"A": ["B", "C"], "B": ["D"], "C": ["E"], "D": [], "E": []}
print(dfs(grafo, "A"))  # ['A', 'B', 'D', 'C', 'E']

def tiene_ciclo(grafo: dict) -> bool:
    """Detecta ciclos en un grafo dirigido con DFS."""
    blanco, gris, negro = 0, 1, 2
    color = {nodo: blanco for nodo in grafo}

    def visitar(v) -> bool:
        color[v] = gris
        for w in grafo.get(v, []):
            if color[w] == gris:
                return True
            if color[w] == blanco and visitar(w):
                return True
        color[v] = negro
        return False

    return any(visitar(v) for v in grafo if color[v] == blanco)

print(tiene_ciclo({"A": ["B"], "B": ["C"], "C": ["A"]}))  # True
print(tiene_ciclo({"A": ["B"], "B": ["C"], "C": []}))      # False

from collections import defaultdict

class Grafo:
    def __init__(self):
        self.adj: dict = defaultdict(list)

    def agregar_arista(self, u, v, dirigido=False):
        self.adj[u].append(v)
        if not dirigido:
            self.adj[v].append(u)

    def vecinos(self, nodo):
        return self.adj[nodo]

g = Grafo()
g.agregar_arista("A", "B")
g.agregar_arista("B", "C")
g.agregar_arista("A", "C")
print(dict(g.adj))

from collections import deque

def camino_mas_corto(grafo: dict, inicio: str, fin: str) -> list | None:
    """BFS para encontrar el camino más corto."""
    cola = deque([(inicio, [inicio])])
    visitados = {inicio}
    while cola:
        nodo, camino = cola.popleft()
        if nodo == fin:
            return camino
        for vecino in grafo.get(nodo, []):
            if vecino not in visitados:
                visitados.add(vecino)
                cola.append((vecino, camino + [vecino]))
    return None

grafo = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": ["E"], "E": []}
print(camino_mas_corto(grafo, "A", "E"))

