    """BFS para encontrar el camino más corto."""
    cola = deque([(inicio, [inicio])])
    visitados = {inicio}
    while cola:
        nodo, camino = cola.popleft()
        if nodo == fin:
            return camino
        for vecino in grafo.get(nodo, []):
            if vecino not in visitados:
                visitados.add(vecino)
                cola.append((vecino, camino + [vecino]))
    return None

grafo = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": ["E"], "E": []}
print(camino_mas_corto(grafo, "A", "E"))

def dfs(grafo: dict, inicio: str, visitados: set = None) -> list:
    """DFS — Búsqueda en Profundidad recursiva."""
    if visitados is None:
        visitados = set()
    visitados.add(inicio)
    orden = [inicio]
    for vecino in grafo.get(inicio, []):
        if vecino not in visitados:
            orden.extend(dfs(grafo, vecino, visitados))
    return orden

grafo = {"A": ["B", "C"], "B": ["D"], "C": ["E"], "D": [], "E": []}
print(dfs(grafo, "A"))  # ['A', 'B', 'D', 'C', 'E']

def tiene_ciclo(grafo: dict) -> bool:
    """Detecta ciclos en un grafo dirigido con DFS."""
    blanco, gris, negro = 0, 1, 2
    color = {nodo: blanco for nodo in grafo}

    def visitar(v) -> bool:
        color[v] = gris
        for w in grafo.get(v, []):
            if color[w] == gris:
                return True
            if color[w] == blanco and visitar(w):
                return True
        color[v] = negro
        return False

    return any(visitar(v) for v in grafo if color[v] == blanco)

print(tiene_ciclo({"A": ["B"], "B": ["C"], "C": ["A"]}))  # True
